1	import { db } from "../lib/db";
2	import { randomBytes } from "node:crypto";
3	import { SANDBOX } from "../lib/sandbox";
4	import { decryptSecret } from "../lib/crypto-box";
5	import {
6	  withServerSsh,
7	  exec,
8	  execInput,
9	  assertDomain,
10	  assertIdent,
11	  assertPath,
12	  assertSlug,
13	  assert,
14	  shellQuote,
15	  SETUP_TIMEOUT_MS,
16	  INSTALL_TIMEOUT_MS,
17	} from "../lib/ssh-exec";
18	import { ensureNginx, ensurePhpFpm, nginxVhost, reloadNginx, sshServer } from "./websites";
19	import { ensureMysql, ensurePostgres } from "./databases";
20	import { appBySlug } from "../lib/cpanel-types";
21	import type { Job } from "@prisma/client";
22	import type { Client } from "ssh2";
23	
24	/**
25	 * Control-panel APP_INSTALL handler (one-click apps).
26	 *
27	 * Registered in worker/index.ts:
28	 *   APP_INSTALL: appInstall,
29	 *
30	 * Reuses the Website + Database primitives: it provisions the vhost + docroot
31	 * (+PHP) and the database, then installs the app. Admin/DB passwords are
32	 * decrypted IN MEMORY, applied, then the encrypted copies are CLEARED.
33	 *
34	 * SANDBOX / non-ENABLE_REAL_CPANEL: no SSH — the site/db/app rows settle to
35	 * ACTIVE with a realistic URL, exactly like the rest of the platform. The real
36	 * path (guarded, off by default) fully installs WordPress; the other catalog
37	 * apps get their site + database provisioned and are marked ready (their
38	 * language runtime setup is intentionally left to the customer — see report).
39	 */
40	
41	const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";
42	
43	async function notify(userId: string, title: string, body?: string, href?: string) {
44	  try {
45	    await db.notification.create({ data: { userId, title, body, href } });
46	  } catch (e) {
47	    console.error("[cpanel/app] notify failed", e);
48	  }
49	}
50	
51	async function loadApp(job: Job) {
52	  const p = (job.payload ?? {}) as { appId?: string };
53	  if (!p.appId) throw new Error("app job: missing appId");
54	  const app = await db.appInstall.findUnique({ where: { id: p.appId } });
55	  if (!app) throw new Error(`AppInstall ${p.appId} not found`);
56	  return app;
57	}
58	
59	/** Create the app's database (MySQL/MariaDB) with the generated password (STDIN). */
60	async function provisionDb(conn: Client, engine: string, name: string, user: string, password: string) {
61	  assertIdent(name, "database name");
62	  assertIdent(user, "database user");
63	  if (engine === "mysql") {
64	    const sql =
65	      `CREATE DATABASE IF NOT EXISTS \`${name}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;\n` +
66	      `CREATE USER IF NOT EXISTS '${user}'@'localhost' IDENTIFIED BY '${password}';\n` +
67	      `GRANT ALL PRIVILEGES ON \`${name}\`.* TO '${user}'@'localhost';\n` +
68	      `FLUSH PRIVILEGES;\n`;
69	    const r = await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
70	    if (r.code !== 0) throw new Error(`database setup failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
71	  } else if (engine === "postgres") {
72	    const sql =
73	      `CREATE ROLE "${user}" LOGIN PASSWORD '${password}';\n` +
74	      `CREATE DATABASE "${name}" OWNER "${user}";\n`;
75	    const r = await execInput(conn, "sudo -u postgres psql -v ON_ERROR_STOP=1", sql, SETUP_TIMEOUT_MS);
76	    if (r.code !== 0) throw new Error(`database setup failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
77	  }
78	}
79	
80	/** Download + configure WordPress core into docRoot with the provisioned DB. */
81	async function installWordpress(
82	  conn: Client,
83	  docRoot: string,
84	  db_: { name: string; user: string; password: string }
85	) {
86	  assertPath(docRoot);
87	  // Fetch + extract core (curl/tar available on the platform base images).
88	  const dl =
89	    `cd ${shellQuote(docRoot)} && curl -fsSL https://wordpress.org/latest.tar.gz -o /tmp/wp.tgz && ` +
90	    `tar -xzf /tmp/wp.tgz --strip-components=1 -C ${shellQuote(docRoot)} && rm -f /tmp/wp.tgz`;
91	  const r = await exec(conn, dl, INSTALL_TIMEOUT_MS);
92	  if (r.code !== 0) throw new Error(`WordPress download failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
93	  // wp-config.php — DB creds live in the file body written via STDIN, never argv.
94	  const salts = `define('AUTH_KEY', '${rand()}');\n`; // minimal; WP still works without unique salts
95	  const cfg =
96	    `<?php\n` +
97	    `define('DB_NAME', '${db_.name}');\n` +
98	    `define('DB_USER', '${db_.user}');\n` +
99	    `define('DB_PASSWORD', '${db_.password}');\n` +
100	    `define('DB_HOST', 'localhost');\n` +
101	    `define('DB_CHARSET', 'utf8mb4');\n` +
102	    `define('DB_COLLATE', '');\n` +
103	    `$table_prefix = 'wp_';\n` +
104	    salts +
105	    `define('WP_DEBUG', false);\n` +
106	    `if ( ! defined('ABSPATH') ) define('ABSPATH', __DIR__ . '/');\n` +
107	    `require_once ABSPATH . 'wp-settings.php';\n`;
108	  await execInput(conn, `cat > ${shellQuote(docRoot + "/wp-config.php")}`, cfg, SETUP_TIMEOUT_MS);
109	  await exec(conn, `chown -R www-data:www-data ${shellQuote(docRoot)} 2>/dev/null || true`, SETUP_TIMEOUT_MS);
110	}
111	
112	function rand(): string {
113	  return randomBytes(24).toString("base64url");
114	}
115	
116	export async function appInstall(job: Job): Promise<void> {
117	  const app = await loadApp(job);
118	  const catalog = appBySlug(app.appSlug);
119	  await db.appInstall.update({ where: { id: app.id }, data: { status: "INSTALLING" } });
120	
121	  try {
122	    assertSlug(app.appSlug);
123	    assertDomain(app.domain);
124	    assert(catalog, `Unknown app: ${app.appSlug}`);
125	
126	    const website = app.websiteId ? await db.website.findUnique({ where: { id: app.websiteId } }) : null;
127	    const database = app.databaseId ? await db.vpsDatabase.findUnique({ where: { id: app.databaseId } }) : null;
128	    const docRoot = website?.docRoot ?? `/var/www/${app.domain}`;
129	    const url = `http://${app.domain}/`;
130	
131	    if (REAL) {
132	      const dbPass = database ? decryptSecret(database.passwordEnc) : null;
133	      const server = await sshServer(app.serverId);
134	      await withServerSsh(server, async (conn) => {
135	        // 1. Site (vhost + docroot + PHP).
136	        await ensureNginx(conn);
137	        if (catalog!.php) await ensurePhpFpm(conn, catalog!.php);
138	        await exec(conn, `mkdir -p ${shellQuote(docRoot)}`, SETUP_TIMEOUT_MS);
139	        const conf = `/etc/nginx/sites-available/${app.domain}.conf`;
140	        const link = `/etc/nginx/sites-enabled/${app.domain}.conf`;
141	        await execInput(conn, `cat > ${shellQuote(conf)}`, nginxVhost(app.domain, docRoot, catalog!.php), SETUP_TIMEOUT_MS);
142	        await exec(conn, `ln -sf ${shellQuote(conf)} ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
143	
144	        // 2. Database.
145	        if (database && dbPass) {
146	          if (database.engine === "mysql") await ensureMysql(conn);
147	          else if (database.engine === "postgres") await ensurePostgres(conn);
148	          await provisionDb(conn, database.engine, database.name, database.dbUser, dbPass);
149	        }
150	
151	        // 3. The app itself.
152	        if (app.appSlug === "wordpress" && database && dbPass) {
153	          await installWordpress(conn, docRoot, { name: database.name, user: database.dbUser, password: dbPass });
154	        } else {
155	          // Provisioned site + DB are ready; drop a landing page. (Language-runtime
156	          // apps like Ghost are intentionally left for the customer to finish.)
157	          await execInput(
158	            conn,
159	            `cat > ${shellQuote(docRoot + "/index.html")}`,
160	            `<!doctype html><meta charset="utf-8"><title>${catalog!.name}</title>` +
161	              `<h1>${catalog!.name} is ready to install</h1>` +
162	              `<p>Your site and database have been provisioned on ${app.domain}. Continue the ${catalog!.name} setup from here.</p>\n`,
163	            SETUP_TIMEOUT_MS
164	          );
165	        }
166	        await exec(conn, `chown -R www-data:www-data ${shellQuote(docRoot)} 2>/dev/null || true`, SETUP_TIMEOUT_MS);
167	        await reloadNginx(conn);
168	      });
169	    }
170	
171	    // Settle the linked rows + clear all transient secrets.
172	    if (website) await db.website.update({ where: { id: website.id }, data: { status: "ACTIVE", ssl: false, error: null } });
173	    if (database) await db.vpsDatabase.update({ where: { id: database.id }, data: { status: "ACTIVE", error: null, passwordEnc: null } });
174	    await db.appInstall.update({
175	      where: { id: app.id },
176	      data: { status: "ACTIVE", url, error: null, adminPassEnc: null },
177	    });
178	
179	    await notify(
180	      app.userId,
181	      `${catalog!.name} installed on ${app.domain}`,
182	      REAL
183	        ? `Your ${catalog!.name} site is live at ${url}. Admin credentials were shown once at install.`
184	        : `${catalog!.name} installed (sandbox — no real VM was touched). URL: ${url}`,
185	      `/dashboard/servers/${app.serverId}?tab=control panel`
186	    );
187	  } catch (e: any) {
188	    const reason = String(e?.message ?? e).slice(0, 400);
189	    // Never keep secrets on a failed install.
190	    if (app.databaseId) await db.vpsDatabase.update({ where: { id: app.databaseId }, data: { status: "FAILED", error: reason, passwordEnc: null } }).catch(() => {});
191	    if (app.websiteId) await db.website.update({ where: { id: app.websiteId }, data: { status: "FAILED", error: reason } }).catch(() => {});
192	    await db.appInstall.update({ where: { id: app.id }, data: { status: "FAILED", error: reason, adminPassEnc: null } });
193	    await notify(app.userId, `${catalog?.name ?? "App"} install failed on ${app.domain}`, reason.slice(0, 200), `/dashboard/servers/${app.serverId}`);
194	  }
195	}
