117	export async function listApps(
118	  serverId: string
119	): Promise<{ ok: true; apps: AppRow[] } | { ok: false; error: string }> {
120	  try {
121	    const { server } = await ownedServer(serverId);
122	    const rows = await db.appInstall.findMany({
123	      where: { serverId: server.id },
124	      orderBy: { createdAt: "desc" },
125	    });
126	    return { ok: true, apps: rows.map(rowOut) };
127	  } catch (err) {
128	    return { ok: false, error: safeError(err) };
129	  }
