132	export async function installApp(
133	  serverId: string,
134	  appSlug: string,
135	  domainInput: string,
136	  adminUserInput?: string
137	): Promise<InstallResult> {
138	  try {
139	    const { user, server } = await ownedServer(serverId);
140	    const limited = throttle(user.id, "install", 6);
141	    if (limited) return { ok: false, error: limited };
142	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to install an app." };
143	    if (await lifecycleBusy(server.id))
144	      return { ok: false, error: "Another server operation is in progress — try again shortly." };
145	
146	    const app = appBySlug(appSlug);
147	    if (!app) return { ok: false, error: "Unknown application." };
148	
149	    const domain = String(domainInput ?? "").toLowerCase().trim().replace(/\.$/, "");
150	    if (!DOMAIN_RE.test(domain))
151	      return { ok: false, error: "Enter a valid domain (e.g. blog.example.com) pointed at this server." };
152	
153	    const adminUser = (String(adminUserInput ?? "admin").replace(/[^a-z0-9_]/gi, "") || "admin").slice(0, 32);
154	
155	    // Domain must be free of an existing website on this server.
156	    const dupSite = await db.website.findFirst({ where: { serverId: server.id, domain } });
157	    if (dupSite) return { ok: false, error: `A website for ${domain} already exists on this server.` };
158	
159	    const adminPassword = generateStrongPassword(18);
160	    const dbName = app.engine ? dbIdentFromDomain(domain, "db") : "";
161	    const dbUser = app.engine ? dbIdentFromDomain(domain, "u") : "";
162	    const dbPassword = app.engine ? generateStrongPassword(20) : "";
163	
164	    // Create the primitives + the install record in one transaction.
165	    const { appRow } = await db.$transaction(async (tx) => {
166	      const website = await tx.website.create({
167	        data: {
168	          userId: user.id,
169	          serverId: server.id,
170	          domain,
171	          docRoot: `/var/www/${domain}`,
172	          phpVersion: app.php,
173	          isSubdomain: domain.split(".").length > 2,
174	          appSlug: app.slug,
175	          status: "PENDING",
176	        },
177	      });
178	      let database: { id: string } | null = null;
179	      if (app.engine) {
180	        database = await tx.vpsDatabase.create({
181	          data: {
182	            userId: user.id,
183	            serverId: server.id,
184	            engine: app.engine,
185	            name: dbName,
186	            dbUser,
187	            passwordEnc: encryptSecret(dbPassword),
188	            status: "PENDING",
189	          },
190	        });
191	      }
192	      const appRow = await tx.appInstall.create({
193	        data: {
194	          userId: user.id,
195	          serverId: server.id,
196	          appSlug: app.slug,
197	          domain,
198	          websiteId: website.id,
199	          databaseId: database?.id ?? null,
200	          adminUser,
201	          adminPassEnc: encryptSecret(adminPassword),
202	          status: "PENDING",
203	        },
204	      });
205	      return { appRow };
206	    });
207	
208	    await db.job.create({ data: { type: "APP_INSTALL", serverId: server.id, payload: { appId: appRow.id } } });
209	    await db.auditLog.create({
210	      data: { userId: user.id, action: "cpanel.app.install", detail: `${app.slug} → ${domain} on ${server.hostname}` },
211	    });
212	    revalidatePath(`/dashboard/servers/${serverId}`);
213	    // Credentials returned ONCE.
214	    return {
215	      ok: true,
216	      id: appRow.id,
217	      domain,
218	      adminUser,
219	      adminPassword,
220	      dbName,
221	      dbUser,
222	      dbPassword,
223	    };
224	  } catch (err) {
225	    return { ok: false, error: safeError(err) };
226	  }
227	}
228	
229	export async function removeApp(id: string): Promise<Result> {
230	  try {
231	    const { user, app } = await ownedApp(id);
232	    const limited = throttle(user.id, "remove", 10);
233	    if (limited) return { ok: false, error: limited };
234	    if (app.status === "INSTALLING") return { ok: false, error: "This app is still installing — try again shortly." };
235	
236	    // Tear down the provisioned site + database via their own worker jobs, then
237	    // drop the AppInstall record. The site/db rows carry the SSH cleanup.
238	    if (app.websiteId) {
239	      const site = await db.website.findUnique({ where: { id: app.websiteId } });
240	      if (site) {
241	        await db.website.update({ where: { id: site.id }, data: { status: "DELETING", appSlug: null } });
242	        await db.job.create({ data: { type: "WEBSITE_DELETE", serverId: app.serverId, payload: { websiteId: site.id } } });
243	      }
244	    }
245	    if (app.databaseId) {
246	      const database = await db.vpsDatabase.findUnique({ where: { id: app.databaseId } });
247	      if (database) {
248	        await db.vpsDatabase.update({ where: { id: database.id }, data: { status: "DELETING" } });
249	        await db.job.create({ data: { type: "DB_DELETE", serverId: app.serverId, payload: { databaseId: database.id } } });
250	      }
251	    }
252	    await db.appInstall.delete({ where: { id } });
253	    await db.auditLog.create({
254	      data: { userId: user.id, action: "cpanel.app.remove", detail: `${app.appSlug} (${app.domain})` },
255	    });
256	    revalidatePath(`/dashboard/servers/${app.serverId}`);
257	    return { ok: true };
258	  } catch (err) {
259	    return { ok: false, error: safeError(err) };
260	  }
261	}
