88	export async function dbCreate(job: Job): Promise<void> {
89	  const row = await loadDb(job);
90	  try {
91	    // Validate again before anything can reach a shell/SQL.
92	    assert(row.engine === "mysql" || row.engine === "postgres", `Unsupported engine: ${row.engine}`);
93	    assertIdent(row.name, "database name");
94	    assertIdent(row.dbUser, "database user");
95	
96	    if (REAL) {
97	      const password = decryptSecret(row.passwordEnc);
98	      assert(password, "Generated password is missing or could not be decrypted.");
99	      const server = await sshServer(row.serverId);
100	      await withServerSsh(server, async (conn) => {
101	        if (row.engine === "mysql") {
102	          await ensureMysql(conn);
103	          // Root socket auth (Debian/Ubuntu default). Password only in the SQL
104	          // body, streamed via STDIN — never an argv token.
105	          const sql =
106	            `CREATE DATABASE IF NOT EXISTS \`${row.name}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;\n` +
107	            `CREATE USER IF NOT EXISTS '${row.dbUser}'@'localhost' IDENTIFIED BY '${password}';\n` +
108	            `ALTER USER '${row.dbUser}'@'localhost' IDENTIFIED BY '${password}';\n` +
109	            `GRANT ALL PRIVILEGES ON \`${row.name}\`.* TO '${row.dbUser}'@'localhost';\n` +
110	            `FLUSH PRIVILEGES;\n`;
111	          const r = await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
112	          if (r.code !== 0) throw new Error(`MySQL create failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
113	        } else {
114	          await ensurePostgres(conn);
115	          // Run as the postgres superuser. Role password only in the SQL body via STDIN.
116	          const sql =
117	            `CREATE ROLE "${row.dbUser}" LOGIN PASSWORD '${password}';\n` +
118	            `CREATE DATABASE "${row.name}" OWNER "${row.dbUser}";\n` +
119	            `GRANT ALL PRIVILEGES ON DATABASE "${row.name}" TO "${row.dbUser}";\n`;
120	          const r = await execInput(conn, "sudo -u postgres psql -v ON_ERROR_STOP=1", sql, SETUP_TIMEOUT_MS);
121	          if (r.code !== 0) throw new Error(`PostgreSQL create failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
122	        }
123	      });
124	    }
125	    // Scrub the transient secret regardless of path.
126	    await db.vpsDatabase.update({ where: { id: row.id }, data: { status: "ACTIVE", error: null, passwordEnc: null } });
127	    await notify(
128	      row.userId,
129	      `Database "${row.name}" is ready`,
130	      REAL ? `Your ${row.engine} database and user are provisioned.` : `Database created (sandbox — no real VM was touched).`,
131	      `/dashboard/servers/${row.serverId}?tab=control panel`
132	    );
133	  } catch (e: any) {
134	    const reason = String(e?.message ?? e).slice(0, 400);
135	    // Even on failure, do not keep the secret around.
136	    await db.vpsDatabase.update({ where: { id: row.id }, data: { status: "FAILED", error: reason, passwordEnc: null } });
137	    await notify(row.userId, `Database "${row.name}" failed`, reason.slice(0, 200), `/dashboard/servers/${row.serverId}`);
138	  }
139	}
